-- Fase 3: áreas de caça com região do mundo e nível de zona; Acampamento Goblin e Floresta dos Ancestrais.
set search_path = public;
update hunts set wregion = case when id = 'ancestrais' then 'ancestrais' else region end, tier = (select tier from world_regions w where w.id = case when hunts.id = 'ancestrais' then 'ancestrais' else hunts.region end) where true;
